"use strict";
const fs=require("node:fs"),path=require("node:path");
const root=path.resolve(__dirname,"..");
const baseline=fs.readFileSync(path.join(root,"tests/ui.test.cjs"),"utf8");
const bootstrap=baseline.slice(0,baseline.indexOf("(async()=>{"));
const checks="\nreturn (async()=>{\n try {\n  w.dispatchEvent(new w.Event(\"pywebviewready\"));await tick();\n  api.start_run=async(...args)=>calls.push([\"start\",...args]);\n  api.stop_run=async(...args)=>calls.push([\"targetedStop\",...args]);\n  let runs=[{session_id:\"demo\",busy:true,state:\"running\"},{session_id:\"other\",busy:false,state:\"idle\"}];\n  let events=[{seq:1,session_id:\"demo\",type:\"text\",data:{text:\"Only chat A\"}}];\n  api.get_events=async(after,sid)=>({events:events.filter(e=>e.seq>after),sequence:events.at(-1)?.seq||0,\n   runs,any_busy:runs.some(r=>r.busy),...runs.find(r=>r.session_id===sid)});\n  await w.loadSession(\"demo\");await w.poll();\n  assert.equal(document.getElementById(\"newChat\").disabled,false);\n  assert.equal(document.getElementById(\"settingsButton\").disabled,true);\n  await w.loadSession(\"other\");await w.poll();\n  assert.equal(document.getElementById(\"prompt\").disabled,false);\n  assert.match(document.getElementById(\"send\").textContent,/Send/);\n  assert.doesNotMatch(document.getElementById(\"messages\").textContent,/Only chat A/);\n  document.getElementById(\"prompt\").value=\"Independent request B\";\n  await w.send();\n  assert.ok(calls.some(c=>c[0]===\"start\"&&c[1]===\"other\"&&c[2]===\"Independent request B\"));\n  await w.send();\n  assert.ok(calls.some(c=>c[0]===\"targetedStop\"&&c[1]===\"other\"));\n  assert.ok(!calls.some(c=>c[0]===\"targetedStop\"&&c[1]===\"demo\"));\n  runs=[{session_id:\"demo\",busy:true,state:\"running\"},{session_id:\"other\",busy:true,state:\"running\"}];\n  events.push({seq:2,session_id:\"other\",type:\"text\",data:{text:\"Only chat B\"}});\n  await w.poll();await w.loadSession(\"demo\");\n  assert.match(document.getElementById(\"messages\").textContent,/Only chat A/);\n  assert.doesNotMatch(document.getElementById(\"messages\").textContent,/Only chat B/);\n  document.getElementById(\"prompt\").value=\"Draft A\";\n  await w.loadSession(\"other\");assert.equal(document.getElementById(\"prompt\").value,\"\");\n  await w.loadSession(\"demo\");assert.equal(document.getElementById(\"prompt\").value,\"Draft A\");\n  api.create_session=async source=>{calls.push([\"parallelChat\",source]);chatRows.push({id:\"parallel\",title:\"Parallel\",project_id:\"\"});return \"parallel\";};\n  document.getElementById(\"prompt\").value=\"Independent third request\";\n  document.getElementById(\"prompt\").dispatchEvent(new w.Event(\"input\"));\n  assert.equal(document.getElementById(\"parallelSend\").hidden,false);\n  document.getElementById(\"parallelSend\").click();await tick();await tick();\n  assert.ok(calls.some(c=>c[0]===\"parallelChat\"&&c[1]===\"demo\"));\n  assert.ok(calls.some(c=>c[0]===\"start\"&&c[1]===\"parallel\"&&c[2]===\"Independent third request\"));\n  await w.showSettings();\n  assert.equal(document.getElementById(\"maxSubagents\").value,\"3\");\n  assert.equal(document.getElementById(\"maxParallelRuns\").value,\"2\");\n  document.getElementById(\"maxSubagents\").value=\"4\";document.getElementById(\"maxParallelRuns\").value=\"3\";\n  await w.saveSettings();\n  const saved=calls.filter(c=>c[0]===\"saveSettings\").at(-1)[1];\n  assert.equal(saved.max_subagents,4);assert.equal(saved.max_parallel_runs,3);\n  w.VeyqI18N.setLanguage(\"it\");await tick();\n  assert.match(document.getElementById(\"maxSubagents\").parentElement.textContent,/Subagenti/);\n  assert.match(document.getElementById(\"maxParallelRuns\").parentElement.textContent,/Richieste parallele/);\n  assert.match(document.getElementById(\"parallelSend\").textContent,/Esegui in parallelo/);\n  console.log(\"Parallel chats, streams/drafts, targeted stop, separate requests and translated limits passed.\");\n } finally {await tick();dispose();}\n})()\n";
new Function("require","__dirname",bootstrap+checks)(require,path.join(root,"tests")).catch(e=>{console.error(e);process.exitCode=1;});
